const summarizeHookDecisions = `-- name: SummarizeHookDecisions :many
SELECT hook, mode, outcome, COUNT(*) AS decisions,
  CAST(COALESCE(SUM(latency_ms), 0) AS bigint) AS total_latency_ms,
  CAST(COALESCE(MAX(latency_ms), 0) AS bigint) AS max_latency_ms
FROM hook_decisions
WHERE decided_at >= $1
GROUP BY hook, mode, outcome
ORDER BY hook, mode, outcome
`

type SummarizeHookDecisionsRow struct {
	Hook           string
	Mode           string
	Outcome        string
	Decisions      int64
	TotalLatencyMs int64
	MaxLatencyMs   int64
}

func (q *Queries) SummarizeHookDecisions(ctx context.Context, decidedAt time.Time) ([]SummarizeHookDecisionsRow, error) {
	rows, err := q.db.Query(ctx, summarizeHookDecisions, decidedAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SummarizeHookDecisionsRow{}
	for rows.Next() {
		var i SummarizeHookDecisionsRow
		if err := rows.Scan(
			&i.Hook,
			&i.Mode,
			&i.Outcome,
			&i.Decisions,
			&i.TotalLatencyMs,
			&i.MaxLatencyMs,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
